using System;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace DeckParty.EditorTools
{
    /// <summary>
    /// Generates the polish assets: the FX Library (Data/FxLibrary.asset) and the Sprite Shaders Ultimate "uber" materials.
    /// SSU effects are shader_feature keywords, so a build only contains effects some saved material uses: the uber
    /// material enables every effect the game drives, with each effect's Fade at 0, and cards fade them in at runtime.
    /// The Feel feedback prefabs are generated by DeckParty.Juice.Editor through <see cref="FeelBuilder"/> (only when
    /// Feel is installed). Nothing here is overwritten later unless you run Deck Party > FX > Rebuild FX (overwrites).
    /// </summary>
    public static class FxSetup
    {
        public const string Folder = "Assets/DeckParty/FX";
        public const string LibraryPath = "Assets/DeckParty/Data/FxLibrary.asset";
        public const string SsuShader = "Sprite Shaders Ultimate/GUI SSU";

        /// <summary>Set by DeckParty.Juice.Editor: builds the Feel feedback prefabs into the library (bool = overwrite).</summary>
        public static Action<FxLibrary, bool> FeelBuilder;

        // Halftone isn't here: it's a "fading" effect measured in sprite-sheet units, so its Fade can't be neutral for every sheet.
        static readonly string[] s_UberEffects =
        {
            "OuterOutline", "Saturation", "SineGlow", "Hologram", "Glitch", "Frozen", "Shine", "Burn", "Poison",
            "AddHue", "FullGlowDissolve", "Pixelate", "Vibrate",
        };

        [MenuItem("Deck Party/FX/Select FX Library", priority = 300)]
        public static void SelectLibrary()
        {
            var library = AssetDatabase.LoadAssetAtPath<FxLibrary>(LibraryPath);
            if (library == null) library = Ensure(false);
            Selection.activeObject = library;
            EditorGUIUtility.PingObject(library);
        }

        [MenuItem("Deck Party/FX/Rebuild FX (overwrites)", priority = 301)]
        public static void RebuildMenu()
        {
            if (!EditorUtility.DisplayDialog("Rebuild FX?", "This regenerates the Feel feedback prefabs and the Sprite Shaders Ultimate materials, discarding your tweaks to them. The FX Library's switches are kept.", "Rebuild", "Cancel"))
                return;
            Ensure(true);
            EditorUtility.DisplayDialog("Deck Party", "FX rebuilt.", "OK");
        }

        public static FxLibrary Ensure(bool overwrite)
        {
            EnsureFolder(Folder + "/Materials");
            EnsureFolder(Folder + "/Feedbacks");
            var library = AssetDatabase.LoadAssetAtPath<FxLibrary>(LibraryPath);
            if (library == null)
            {
                library = ScriptableObject.CreateInstance<FxLibrary>();
                AssetDatabase.CreateAsset(library, LibraryPath);
            }
            library.EnsureAllCues();

            if (library.portraitUber == null || overwrite) library.portraitUber = UberMaterial("PortraitUber", overwrite);
            else RepairFadingEffects(library.portraitUber);
            if (library.shineUber == null || overwrite) library.shineUber = ShineMaterial(overwrite);

            if (FeelBuilder != null)
            {
                try { FeelBuilder(library, overwrite); }
                catch (Exception e) { Debug.LogException(e); }
            }
            else
            {
                Debug.Log("[DeckParty] Feel isn't installed (or DeckParty.Juice didn't compile): effects use the built-in tweens.");
            }

            EditorUtility.SetDirty(library);
            var db = AssetDatabase.LoadAssetAtPath<GameDatabase>(DeckPartyPaths.Database);
            if (db != null && db.fx == null)
            {
                db.fx = library;
                EditorUtility.SetDirty(db);
            }
            AssetDatabase.SaveAssets();
            return library;
        }

        /// <summary>One material with every driven SSU effect switched on and faded out (Fade 0).</summary>
        static Material UberMaterial(string name, bool overwrite)
        {
            string path = $"{Folder}/Materials/{name}.mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material != null && !overwrite) return material;
            var shader = Shader.Find(SsuShader);
            if (shader == null)
            {
                Debug.LogWarning("[DeckParty] Sprite Shaders Ultimate isn't installed: card status effects are off.");
                return null;
            }
            if (material == null)
            {
                material = new Material(shader) { name = name };
                AssetDatabase.CreateAsset(material, path);
            }
            material.shader = shader;
            foreach (var effect in s_UberEffects)
            {
                material.EnableKeyword($"_ENABLE{effect.ToUpperInvariant()}_ON");
                SetFloat(material, $"_Enable{effect}", 1f);
                SetFloat(material, $"_{effect}Fade", 0f);
            }
            SetFloat(material, "_Saturation", 1f);
            SetFloat(material, "_OuterOutlineWidth", 0.03f);
            SetFloat(material, "_ShineWidth", 0.12f);
            SetFloat(material, "_ShineSpeed", 0.6f);
            RepairFadingEffects(material);
            EditorUtility.SetDirty(material);
            return material;
        }

        /// <summary>
        /// Halftone and Full Glow Dissolve are SSU "fading" effects (Fade = how much of the sprite remains), so a Fade of 0
        /// makes portraits invisible. Materials generated before this fix had Halftone switched on at 0, which hid every
        /// card portrait: this switches Halftone off and leaves Full Glow Dissolve fully visible.
        /// </summary>
        static void RepairFadingEffects(Material material)
        {
            if (material == null) return;
            bool changed = false;
            if (material.IsKeywordEnabled("_ENABLEHALFTONE_ON"))
            {
                material.DisableKeyword("_ENABLEHALFTONE_ON");
                changed = true;
            }
            if (material.HasProperty("_EnableHalftone") && material.GetFloat("_EnableHalftone") != 0f)
            {
                material.SetFloat("_EnableHalftone", 0f);
                changed = true;
            }
            if (material.HasProperty("_HalftoneFade") && material.GetFloat("_HalftoneFade") < CardFx.HalftoneClear)
            {
                material.SetFloat("_HalftoneFade", CardFx.HalftoneClear);
                changed = true;
            }
            // Full Glow Dissolve: 1 = fully visible (the card dissolves in from 0 when a viewer joins).
            if (material.HasProperty("_FullGlowDissolveFade") && material.GetFloat("_FullGlowDissolveFade") < 1f)
            {
                material.SetFloat("_FullGlowDissolveFade", 1f);
                changed = true;
            }
            if (changed) EditorUtility.SetDirty(material);
        }

        /// <summary>A shine-only material for buttons and banners that sparkle (End the Stream at 4 Diamonds).</summary>
        static Material ShineMaterial(bool overwrite)
        {
            string path = $"{Folder}/Materials/ShineUber.mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material != null && !overwrite) return material;
            var shader = Shader.Find(SsuShader);
            if (shader == null) return null;
            if (material == null)
            {
                material = new Material(shader) { name = "ShineUber" };
                AssetDatabase.CreateAsset(material, path);
            }
            material.EnableKeyword("_ENABLESHINE_ON");
            SetFloat(material, "_EnableShine", 1f);
            SetFloat(material, "_ShineFade", 1f);
            SetFloat(material, "_ShineSpeed", 0.5f);
            EditorUtility.SetDirty(material);
            return material;
        }

        static void SetFloat(Material material, string property, float value)
        {
            if (material.HasProperty(property)) material.SetFloat(property, value);
        }

        static void EnsureFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path)) return;
            var parent = Path.GetDirectoryName(path).Replace('\\', '/');
            EnsureFolder(parent);
            AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
        }
    }
}
